package org.sleepwell.app;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class TagImpactTest {
 RecordEntry record(long id,long start,int minutes,String...tags){RecordDraft draft=new RecordDraft(start,start+minutes*60000L);for(String tag:tags)draft.addTag(tag);return new RecordEntry(id,draft.start,draft.end,null,"manual","local","UTC",0,0,draft,true,id,List.of());}
 @Test public void groupsUseActualDurationsAndCaseInsensitivePresence(){RecordEntry a=record(1,100000,360,"Coffee"),b=record(2,90000000,480);TagImpact result=new TagImpact(List.of(a,b),"coffee",200000000);assertEquals(1,result.tagged.count);assertEquals(360*60000L,result.tagged.mean);assertEquals(480*60000L,result.other.mean);assertEquals(2,result.manual);}
 @Test public void emptyGroupIsMissingNotZeroSleep(){TagImpact result=new TagImpact(List.of(record(1,100000,360)),"Coffee",50000000);assertEquals(0,result.tagged.count);assertEquals(1,result.other.count);}
 @Test public void overlapExcludesEveryAmbiguousRecordIncludingContainedOnes(){TagImpact result=new TagImpact(List.of(record(1,100000,480,"Coffee"),record(2,100001,60),record(3,100002,30)),"Coffee",50000000);assertEquals(3,result.skipped);assertEquals(0,result.tagged.count+result.other.count);}
 @Test public void touchingPeriodsAreIndependentAndAwakeEditsActuallyReduceDuration(){RecordEntry a=record(1,100000,60,"Coffee"),b=record(2,3700000,60);a.edit.awake.add(new RecordIntervals.Span(100000,700000));TagImpact result=new TagImpact(List.of(a,b),"Coffee",10000000);assertEquals(0,result.skipped);assertEquals(50*60000L,result.tagged.mean);}
 @Test public void napsAndFutureDoNotBecomeComparators(){TagImpact result=new TagImpact(List.of(record(1,100000,60,"Nap"),record(2,100000000,60,"Coffee")),"Coffee",50000000);assertEquals(2,result.skipped);assertEquals(0,result.tagged.count+result.other.count);}
 @Test public void quantitiesKeepUnitsSeparateAndBareTagsUnknown(){RecordEntry a=record(1,100000,60,"Coffee"),b=record(2,9000000,60,"Coffee"),c=record(3,18000000,60,"Coffee");a.edit.quantity("Coffee",new TagQuantity(2,"cups"));b.edit.quantity("Coffee",new TagQuantity(80,"mg"));TagImpact result=new TagImpact(List.of(a,b,c),"Coffee",50000000);assertEquals(2,result.quantified);assertEquals(3,result.tagged.count);assertEquals(List.of(2d),result.quantities.get("cups"));assertEquals(List.of(80d),result.quantities.get("mg"));}
 @Test public void sortedMedianIsComputedIndependentlyOfInputOrder(){TagImpact result=new TagImpact(List.of(record(1,100000,60,"x"),record(2,9000000,120,"x"),record(3,18000000,90,"x")),"x",50000000);assertEquals(90*60000L,result.tagged.median);}
 @Test public void quantityCopiesAndRemovalCannotLeaveOrphanedMetadata(){RecordDraft draft=record(1,100000,60,"x").edit;draft.quantity("x",new TagQuantity(0,"cups"));RecordDraft copy=draft.copy();copy.removeTag("x");assertEquals(1,draft.quantities.size());assertTrue(copy.quantities.isEmpty());assertEquals("0 cups",draft.quantities.get("x").display());}
 @Test public void invalidQuantitiesAndOrphansAreRejected(){for(double value:new double[]{-1,Double.NaN,Double.POSITIVE_INFINITY,1000001})assertThrows(IllegalArgumentException.class,()->new TagQuantity(value,"mg"));assertThrows(IllegalArgumentException.class,()->new TagQuantity(1,"x".repeat(25)));RecordDraft draft=record(1,100000,60).edit;assertThrows(IllegalArgumentException.class,()->draft.quantity("missing",new TagQuantity(1,"mg")));}
 @Test public void regionalDecimalInputUsesRealDecimalDigits(){assertEquals(2.5,TagQuantity.parse("٢٫٥"),0);assertEquals(12.5,TagQuantity.parse("۱۲.۵"),0);for(String bad:List.of("1e3","-1","½","1,000","."))assertThrows(IllegalArgumentException.class,()->TagQuantity.parse(bad));}
 @Test public void quantitativeAssociationUsesPairedActualDurations(){RecordEntry a=record(1,100000,60,"x"),b=record(2,9000000,120,"x"),c=record(3,18000000,180,"x");a.edit.quantity("x",new TagQuantity(1,"cups"));b.edit.quantity("x",new TagQuantity(2,"cups"));c.edit.quantity("x",new TagQuantity(3,"cups"));TagImpact result=new TagImpact(List.of(a,b,c),"x",50000000);assertEquals(1,result.quantityStats.get("cups").correlation,0.00001);assertEquals(3,result.quantityStats.get("cups").count);}
 @Test public void constantOrTooFewQuantitiesCannotClaimCorrelation(){assertNull(new TagImpact.QuantityGroup(List.of(2d,2d,2d),List.of(1d,2d,3d)).correlation);assertNull(new TagImpact.QuantityGroup(List.of(1d,2d),List.of(3d,4d)).correlation);assertNull(new TagImpact.QuantityGroup(List.of(1d,2d,3d),List.of(4d,4d,4d)).correlation);}
 @Test public void quantitativeAssociationPreservesNegativeDirection(){assertEquals(-1,new TagImpact.QuantityGroup(List.of(1d,2d,3d),List.of(3d,2d,1d)).correlation,0.00001);}
 @Test public void inputNamesRemainLegacyCompatible(){RecordDraft draft=record(1,100000,60,"#Coffee").edit;draft.addTag("coffee");assertEquals(List.of("Coffee"),draft.tags);assertEquals(List.of("Coffee"),TagImpact.names(List.of(record(1,100000,60,"Coffee"),record(2,9000000,60,"coffee"))));}
}
